css:
.voucher-batch-print {
	--primary-blue: #2F70F8;
	--text-primary: #FFFFFF;
	--text-secondary: #A39EB0;
	--text-faint: rgba(163, 158, 176, 0.6);
	--glass-card-bg: rgba(59, 53, 72, 0.9);
	--glass-inner-bg: #2B2636;
	--glass-border: rgba(90, 82, 106, 0.4);

	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
	background-color: #4338CA;
	background-image:
		radial-gradient(circle at 15% 10%, #DB2777e6, transparent 55%),
		radial-gradient(circle at 85% 88%, #4338CAd9, transparent 55%),
		linear-gradient(135deg, #DB2777 0%, #7C3AED 45%, #4338CA 100%);
	padding: 20px;
}
.voucher-batch-print .batch-header { color: var(--text-primary); margin-bottom: 16px; }
.voucher-batch-print .batch-header .brand { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-secondary); }
.voucher-batch-print .batch-header .batch-meta { display: flex; flex-wrap: wrap; gap: 14px; font-size: 13px; font-weight: 700; margin-top: 4px; }
.voucher-batch-print .voucher-grid { display: flex; flex-wrap: wrap; gap: 14px; }
.voucher-batch-print .voucher-card {
	width: 230px;
	background: var(--glass-card-bg);
	border: 1px solid var(--glass-border);
	border-radius: 20px;
	padding: 16px 14px;
	text-align: center;
	box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.6);
}
.voucher-batch-print .v-wifi { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--text-secondary); }
.voucher-batch-print .v-code {
	margin-top: 10px;
	background: var(--glass-inner-bg);
	border: 1.5px solid var(--glass-border);
	border-radius: 14px;
	padding: 12px 8px;
	font-size: 24px;
	font-weight: 800;
	letter-spacing: 4px;
	color: var(--primary-blue);
}
.voucher-batch-print .v-meta { display: flex; justify-content: space-between; margin-top: 10px; font-size: 12px; font-weight: 600; color: var(--text-primary); }
.voucher-batch-print .v-sub { margin-top: 4px; font-size: 10.5px; color: var(--text-faint); }
